"use client";

import { useState, useEffect } from "react";
import { GodLights } from "godlights";
import type { SceneConfig } from "godlights";

const INTERVAL_MS = 4000;
const FADE_MS = 800;

const defaultPresets: SceneConfig[] = [
  {
    width: 1920,
    height: 1080,
    noise: 8,
    grainSize: 1,
    layers: [
      {
        id: "background",
        type: "background",
        bgType: "solid",
        bgColor: "#06060f",
        bgColor2: "#06060f",
        bgGradientAngle: 180,
      },
      {
        id: "halo-1",
        name: "Halo",
        type: "halo",
        originX: 20,
        originY: 5,
        color: "#a78bfa",
        intensity: 0.3,
        size: 0.5,
        blendMode: "lighter",
      },
      {
        id: "rays-1",
        name: "Rays",
        type: "rays",
        direction: 160,
        spread: 70,
        originX: 20,
        originY: 5,
        rayCount: 24,
        rayWidth: 70,
        divergence: 1.8,
        rayLength: 1.0,
        colorStart: "#a78bfa",
        colorEnd: "#a78bfa",
        opacity: 0.18,
        blendMode: "screen",
        fadeToTransparent: true,
        blur: 12,
        randomnessWidth: 60,
        randomnessLength: 20,
        randomnessAngle: 15,
        seed: 1,
      },
    ],
  },
  {
    width: 1920,
    height: 1080,
    noise: 8,
    grainSize: 1,
    layers: [
      {
        id: "background",
        type: "background",
        bgType: "solid",
        bgColor: "#060f08",
        bgColor2: "#060f08",
        bgGradientAngle: 180,
      },
      {
        id: "halo-1",
        name: "Halo",
        type: "halo",
        originX: 80,
        originY: 5,
        color: "#34d399",
        intensity: 0.3,
        size: 0.5,
        blendMode: "lighter",
      },
      {
        id: "rays-1",
        name: "Rays",
        type: "rays",
        direction: 200,
        spread: 70,
        originX: 80,
        originY: 5,
        rayCount: 24,
        rayWidth: 70,
        divergence: 1.8,
        rayLength: 1.0,
        colorStart: "#34d399",
        colorEnd: "#34d399",
        opacity: 0.18,
        blendMode: "screen",
        fadeToTransparent: true,
        blur: 12,
        randomnessWidth: 60,
        randomnessLength: 20,
        randomnessAngle: 15,
        seed: 2,
      },
    ],
  },
  {
    width: 1920,
    height: 1080,
    noise: 8,
    grainSize: 1,
    layers: [
      {
        id: "background",
        type: "background",
        bgType: "solid",
        bgColor: "#0f0608",
        bgColor2: "#0f0608",
        bgGradientAngle: 180,
      },
      {
        id: "halo-1",
        name: "Halo",
        type: "halo",
        originX: 50,
        originY: 5,
        color: "#f87171",
        intensity: 0.3,
        size: 0.5,
        blendMode: "lighter",
      },
      {
        id: "rays-1",
        name: "Rays",
        type: "rays",
        direction: 180,
        spread: 70,
        originX: 50,
        originY: 5,
        rayCount: 24,
        rayWidth: 70,
        divergence: 1.8,
        rayLength: 1.0,
        colorStart: "#f87171",
        colorEnd: "#f87171",
        opacity: 0.18,
        blendMode: "screen",
        fadeToTransparent: true,
        blur: 12,
        randomnessWidth: 60,
        randomnessLength: 20,
        randomnessAngle: 15,
        seed: 3,
      },
    ],
  },
];

const fillStyle: React.CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
};

interface GodLightsCyclingProps {
  presets?: SceneConfig[];
  intervalMs?: number;
  fadeMs?: number;
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

export function GodLightsCycling({
  presets = defaultPresets,
  intervalMs = INTERVAL_MS,
  fadeMs = FADE_MS,
  children,
  className,
  style,
}: GodLightsCyclingProps) {
  const [current, setCurrent] = useState(0);
  const [next, setNext] = useState(1 % presets.length);
  const [fading, setFading] = useState(false);

  useEffect(() => {
    const id = setInterval(() => {
      const nextIndex = (current + 1) % presets.length;
      setNext(nextIndex);
      setFading(true);
      setTimeout(() => {
        setCurrent(nextIndex);
        setFading(false);
      }, fadeMs);
    }, intervalMs);
    return () => clearInterval(id);
  }, [current, presets.length, intervalMs, fadeMs]);

  return (
    <div
      className={className}
      style={{ position: "relative", ...style }}
    >
      <GodLights scene={presets[current]} animate style={fillStyle} />
      <GodLights
        scene={presets[next]}
        animate={fading}
        style={{
          ...fillStyle,
          opacity: fading ? 1 : 0,
          transition: `opacity ${fadeMs}ms ease`,
        }}
      />
      {children && (
        <div style={{ position: "relative", zIndex: 1 }}>{children}</div>
      )}
    </div>
  );
}
